  while (lines.length && (/^\s*(#[^\s#]+\s*)+$/.test(lines[lines.length - 1]) || !lines[lines.length - 1].trim())) {
    tags.push(...(lines.pop().match(/#[^\s#]+/g) || []));
  }
  caption = lines.join("\n").trim();
  if (caption) {
    const allowed = new Set(bai.cakes.map(c => Number(c.price)));
