function geminiText(r) {
  const parts = (r && r.candidates && r.candidates[0] && r.candidates[0].content && r.candidates[0].content.parts) || [];
  return parts.filter(p => p.text && !p.thought).map(p => p.text).join("").trim();
}
function geminiJson(r) {
